INSERT INTO `menus` (`menu_id`, `nom_menu`, `theme`, `description`, `date_debut_disponibilite`, `date_fin_disponibilite`, `conditions`, `personnes_minimum`, `prix_par_personne`, `stock_disponible`, `materiel_disponible`, `actif`, `image_url`, `image_alt`) VALUES (1,'Menu Découverte','Classique','Le Menu Découverte est une invitation à découvrir les spécialités de Vite & Gourmand. Composé de recettes gourmandes et soigneusement élaborées, il offre un parfait équilibre entre simplicité, authenticité et générosité pour une première expérience culinaire pleine de saveurs.\r\n',NULL,NULL,'Commande à effectuer au minimum 5 jours avant la date de votre événement.\r\nLes plats sont livrés prêts à être dégustés ou accompagnés d\'une fiche de remise en température.\r\nLes préparations doivent être conservées entre 0 °C et 4 °C jusqu\'au moment du service.\r\nLes produits sont à consommer dans les 24 heures suivant la livraison.\r\nAucun matériel de service ou de maintien au chaud n\'est fourni avec ce menu.\r\n',8,45.00,24,0,1,'assets/menus/classiques/decouverte/decouverte_menu.png','Image du Menu Découverte'),(2,'Menu Signature','Classique','Le Menu Signature met à l\'honneur les recettes emblématiques de Vite & Gourmand. Élaboré à partir d\'ingrédients soigneusement sélectionnés, il reflète tout notre savoir-faire culinaire à travers des associations de saveurs raffinées et des plats généreux, pensés pour offrir une expérience gastronomique inoubliable.',NULL,NULL,'Commande à effectuer au minimum 7 jours avant la date de votre événement.\r\nLes plats sont livrés prêts à être dégustés ou accompagnés d\'une fiche de remise en température.\r\nLes préparations doivent être conservées entre 0 °C et 4 °C jusqu\'au moment du service.\r\nLes produits sont à consommer dans les 24 heures suivant la livraison.\r\nVaisselle, nappage et matériel de service non inclus.',5,55.00,10,0,1,'assets/menus/classiques/signature/signature_menu.png','Image du Menu Signature'),(3,'Menu Prestige','Classique','Le Menu Prestige incarne l\'excellence de Vite & Gourmand. Pensé pour les occasions les plus marquantes, il réunit des produits d\'exception, des recettes raffinées et une présentation soignée afin d\'offrir une expérience gastronomique élégante et mémorable.\r\n',NULL,NULL,'Commande à effectuer au minimum 14 jours avant la date de votre événement.\r\nCertaines préparations étant réalisées à la demande, aucune modification ne pourra être effectuée moins de 7 jours avant la prestation.\r\nLes plats sont livrés froids avec une fiche détaillée de remise en température.\r\nConservation obligatoire entre 0 °C et 4 °C jusqu\'au service.\r\nLes préparations sont à consommer dans les 24 heures suivant la livraison.\r\nLocation de vaisselle, nappage, mobilier et personnel de service disponibles en option.\r\n',5,70.00,15,1,1,'assets/menus/classiques/prestige/prestige_menu.png','Image du Menu Prestige'),(4,'Menu Terroir','Classique','Le Menu Terroir célèbre les richesses gastronomiques du Sud-Ouest et de la région bordelaise. Élaboré à partir de produits locaux et de recettes traditionnelles revisitées, il met à l\'honneur les saveurs authentiques qui font la renommée de notre terroir.\r\n',NULL,NULL,'Commande à effectuer au minimum 10 jours avant la date de votre événement.\r\nLes plats sont préparés exclusivement à partir de produits frais et de saison.\r\nLivraison avec fiche de remise en température pour préserver toutes les saveurs.\r\nLes préparations doivent être conservées entre 0 °C et 4 °C.\r\nLes produits sont à consommer dans les 24 heures suivant la livraison.\r\nAucun matériel de service n\'est fourni avec ce menu.\r\n',5,55.00,10,0,1,'assets/menus/classiques/terroir/terroir_menu.png','Image du Menu Terroir'),(5,'Menu Mariage','Événementiel','Le Menu Mariage a été imaginé pour sublimer le plus beau jour de votre vie. Des produits d\'exception, des recettes raffinées et une présentation élégante se réunissent pour offrir à vos invités une expérience culinaire inoubliable, à la hauteur de cet événement unique.\r\n',NULL,NULL,'Commande à effectuer au minimum 2 mois avant la date du mariage.\r\nLe nombre définitif de convives devra être confirmé 15 jours avant la prestation.\r\nLes plats sont préparés le jour même afin de garantir une fraîcheur optimale.\r\nConservation entre 0 °C et 4 °C jusqu\'au service.\r\nLes préparations sont à consommer le jour de la prestation.\r\nLe menu peut être livré chaud ou froid selon la prestation choisie.\r\nLocation de vaisselle, nappage, mobilier et personnel de service disponibles en option.\r\nUne dégustation peut être organisée avant la validation définitive du menu.\r\n',25,120.00,50,1,1,'assets/menus/evenementiels/mariage/mariage_menu.png','Image du Menu Mariage'),(6,'Menu Séminaire','Événementiel','Le Menu Séminaire a été conçu pour accompagner vos événements professionnels avec élégance et simplicité. Composé de produits frais et de recettes équilibrées, il offre un repas raffiné qui favorise les échanges entre collaborateurs tout en garantissant une expérience gourmande et conviviale.\r\n',NULL,NULL,'Commande à effectuer au minimum 1 mois avant la prestation.\r\nConfirmation du nombre définitif de participants 1 semaine avant la livraison.\r\nLes plats sont préparés le jour de la prestation afin de garantir leur fraîcheur.\r\nConservation entre 0 °C et 4 °C jusqu\'au service.\r\nLivraison directement sur votre lieu de séminaire ou dans vos locaux.\r\nLes plats sont livrés prêts à être servis ou accompagnés d\'une fiche de remise en température.\r\nLocation de vaisselle, nappage, mobilier et personnel de service disponibles en option.\r\n',15,90.00,45,1,1,'assets/menus/evenementiels/seminaire/seminaire_menu.png','Image du Menu Séminaire'),(7,'Menu Anniversaire','Événementiel','Le Menu Anniversaire a été imaginé pour célébrer les moments qui comptent. Entre recettes gourmandes, produits de qualité et présentation soignée, il accompagne petits et grands événements dans une ambiance chaleureuse et festive. Chaque plat est pensé pour réunir vos invités autour d\'un repas généreux qui laissera de délicieux souvenirs.\r\n',NULL,NULL,'Commande à effectuer au minimum 14 jours avant la prestation.\r\nLe nombre définitif de convives devra être confirmé 5 jours avant la livraison.\r\nLes plats sont préparés à partir de produits frais et livrés avec une fiche de remise en température.\r\nConservation entre 0 °C et 4 °C jusqu\'au moment du service.\r\nLes préparations sont à consommer dans les 24 heures suivant la livraison.\r\nLocation de vaisselle, nappage, mobilier et personnel de service disponibles en option.\r\n',10,50.00,30,1,1,'assets/menus/evenementiels/anniversaire/anniversaire_menu.png','Image du Menu Anniversaire'),(8,'Menu Saveurs de printemps','Saisonnier','Le Menu Saveurs de Printemps célèbre le retour des beaux jours à travers une cuisine fraîche, colorée et de saison. Élaboré avec des légumes primeurs, des herbes fraîches et des fruits printaniers, il met à l\'honneur la légèreté et la gourmandise pour un repas plein de fraîcheur.\r\n','2027-03-21','2021-06-20','Commande à effectuer au minimum 7 jours avant la prestation.\r\nCe menu est proposé uniquement durant la saison printanière, selon la disponibilité des produits frais.\r\nLes légumes et fruits sont sélectionnés quotidiennement auprès de producteurs locaux lorsque cela est possible.\r\nConservation obligatoire entre 0 °C et 4 °C jusqu\'au service.\r\nLes préparations sont à consommer dans les 24 heures suivant la livraison.\r\nLes plats sont livrés prêts à être dégustés ou accompagnés d\'une fiche de remise en température.',5,45.00,0,0,0,'assets/menus/saisonniers/printemps/saveurs_printemps/saveurs_printemps_menu.png','Image du Menu Saveurs de printemps'),(9,'Menu de Pâques','Saisonnier','Le Menu de Pâques met à l\'honneur les traditions gourmandes de cette fête familiale à travers des produits de saison et des recettes raffinées. Entre l\'agneau fondant, les légumes printaniers et une touche chocolatée en dessert, ce menu offre un repas généreux et festif pour célébrer Pâques autour d\'une belle table.\r\n','2027-02-27','2027-03-29','Commande à effectuer au minimum 10 jours avant la prestation.\r\nMenu proposé uniquement durant la période de Pâques, dans la limite des stocks disponibles.\r\nLes produits sont préparés exclusivement à partir d\'ingrédients frais et de saison.\r\nConservation entre 0 °C et 4 °C jusqu\'au service.\r\nLes préparations sont à consommer dans les 24 heures suivant la livraison.\r\nLocation de vaisselle, nappage, mobilier et personnel de service disponibles en option.\r\nLes plats sont livrés prêts à être servis ou accompagnés d\'une fiche de remise en température.',8,55.00,0,1,0,'assets/menus/saisonniers/printemps/paques/paques_menu.png','Image du Menu de Pâques'),(10,'Menu Saveurs d\'été','Saisonnier','Le Menu Saveurs d\'Été met à l\'honneur les plus beaux produits de la saison à travers une cuisine ensoleillée, colorée et généreuse. Entre légumes gorgés de soleil, herbes fraîches et fruits estivaux, il offre un repas raffiné qui évoque les longues journées d\'été et les repas partagés en toute convivialité.\r\n','2026-06-21','2026-09-22','Commande à effectuer au minimum 7 jours avant la prestation.\r\nMenu disponible uniquement durant la saison estivale, selon la disponibilité des produits frais.\r\nLes ingrédients sont sélectionnés quotidiennement afin de garantir leur fraîcheur.\r\nConservation entre 0 °C et 4 °C jusqu\'au service.\r\nLes préparations sont à consommer dans les 24 heures suivant la livraison.\r\nLes plats sont livrés prêts à être dégustés ou accompagnés d\'une fiche de remise en température.\r\n',5,45.00,25,0,1,'assets/menus/saisonniers/ete/saveurs_ete/saveurs_ete_menu.png','Image du Menu Saveurs d\'été'),(11,'Menu Garden party','Saisonnier','Le Menu Garden Party a été imaginé pour vos repas en extérieur, dans une ambiance élégante et conviviale. Inspiré des déjeuners d\'été au jardin, il associe des produits frais, des saveurs ensoleillées et une présentation raffinée afin de partager un moment gourmand au grand air.\r\n','2026-07-01','2026-08-31','Commande à effectuer au minimum 7 jours avant la prestation.\r\nMenu disponible durant la période estivale.\r\nLes plats sont préparés le jour de la livraison afin de garantir leur fraîcheur.\r\nConservation entre 0 °C et 4 °C jusqu\'au moment du service.\r\nLes préparations sont à consommer dans les 24 heures suivant la livraison.\r\nLocation de vaisselle, nappage, mobilier et personnel de service disponibles en option.\r\nEn cas de prestation en extérieur, un espace ombragé est recommandé pour préserver la qualité des aliments',8,55.00,40,1,1,'assets/menus/saisonniers/ete/garden_party/garden_party_menu.png','Image du Menu Garden party'),(12,'Menu Saveurs d\'automne','Saisonnier','Le Menu Saveurs d\'Automne met à l\'honneur les richesses de la saison à travers une cuisine généreuse et raffinée. Entre légumes anciens, champignons forestiers, châtaignes et fruits d\'automne, il offre un repas chaleureux aux saveurs authentiques, idéal pour profiter des premiers jours de fraîcheur.\r\n','2026-09-23','2026-12-20','Commande à effectuer au minimum 7 jours avant la prestation.\r\nMenu disponible uniquement durant la saison automnale, selon la disponibilité des produits.\r\nLes légumes, champignons et fruits sont sélectionnés auprès de producteurs locaux lorsque cela est possible.\r\nConservation entre 0 °C et 4 °C jusqu\'au service.\r\nLes préparations sont à consommer dans les 24 heures suivant la livraison.\r\nLes plats sont livrés prêts à être servis ou accompagnés d\'une fiche de remise en température.',5,45.00,0,0,0,'assets/menus/saisonniers/automne/saveurs_automne/saveurs_automne_menu.png','Image du Menu Saveurs d\'automne'),(13,'Menu Vendange','Saisonnier','Le Menu Vendanges célèbre l\'un des temps forts du patrimoine bordelais. Inspiré des saveurs de la fin de l\'été et du début de l\'automne, il met à l\'honneur les produits emblématiques de la saison tels que les raisins, les figues, les noix et les champignons. Un menu généreux et raffiné qui évoque les grandes tablées des domaines viticoles.\r\nLocation de vaisselle, nappage, mobilier et personnel de service disponibles en option.\r\n','2026-09-01','2026-10-17','Commande à effectuer au minimum 7 jours avant la prestation.\r\nMenu disponible uniquement pendant la période des vendanges (septembre à octobre), selon la disponibilité des produits de saison.\r\nLes fruits frais sont sélectionnés quotidiennement afin de garantir leur qualité.\r\nConservation entre 0 °C et 4 °C jusqu\'au service.\r\nLes préparations sont à consommer dans les 24 heures suivant la livraison.\r\nLes plats sont livrés prêts à être servis ou accompagnés d\'une fiche de remise en température.\r\n',8,55.00,0,1,0,'assets/menus/saisonniers/automne/vendange/vendange_menu.png','Image du Menu Vendange'),(14,'Menu Saveurs d\'hiver','Saisonnier','Le Menu Saveurs d\'Hiver célèbre les produits généreux de la saison à travers une cuisine chaleureuse et raffinée. Entre légumes oubliés, viandes fondantes, agrumes et épices délicates, il offre un repas réconfortant où authenticité et gourmandise se rencontrent pour sublimer les journées d\'hiver.\r\n','2026-12-21','2027-03-19','Commande à effectuer au minimum 7 jours avant la prestation.\r\nMenu disponible uniquement durant la saison hivernale, selon la disponibilité des produits.\r\nLes préparations mijotées sont réalisées le jour précédant la livraison afin de développer pleinement leurs saveurs.\r\nConservation entre 0 °C et 4 °C jusqu\'au service.\r\nLes plats sont à consommer dans les 24 heures suivant la livraison.\r\nLes plats sont livrés prêts à être servis ou accompagnés d\'une fiche de remise en température.\r\n',5,45.00,0,0,0,'assets/menus/saisonniers/hiver/saveurs_hiver/saveurs_hiver_menu.png','Image du Menu Saveurs d\'hiver'),(15,'Menu Noël Gourmand','Saisonnier','','2026-11-01','2026-12-15','Commande à effectuer au minimum 10 jours avant la prestation.\r\nMenu disponible exclusivement durant les fêtes de fin d\'année.\r\nLes produits festifs étant proposés en quantité limitée, la réservation est conseillée plusieurs semaines à l\'avance.\r\nConservation entre 0 °C et 4 °C jusqu\'au moment du service.\r\nLes préparations sont à consommer dans les 24 heures suivant la livraison.\r\nLocation de vaisselle, nappage, mobilier et personnel de service disponibles en option.',8,75.00,0,1,0,'assets/menus/saisonniers/hiver/noel_gourmand/noel_gourmand_menu.png','Image du Menu Noël Gourmand'),(16,'Végétarien - Menu Jardin gourmand','Régime particulier','Le Menu Jardin Gourmand met à l\'honneur la richesse du monde végétal à travers une cuisine créative, colorée et raffinée. Élaboré à partir de légumes de saison, de céréales, de champignons et de produits du terroir, il propose une expérience gastronomique généreuse où chaque ingrédient révèle pleinement ses saveurs.\r\n',NULL,NULL,'Commande à effectuer au minimum 7 jours avant la prestation.\r\nLes légumes sont sélectionnés en priorité auprès de producteurs locaux et selon les disponibilités saisonnières.\r\nConservation entre 0 °C et 4 °C jusqu\'au moment du service.\r\nLes préparations sont à consommer dans les 24 heures suivant la livraison.\r\nLes plats sont livrés prêts à être servis ou accompagnés d\'une fiche de remise en température.\r\nCertaines garnitures peuvent varier légèrement en fonction des produits de saison tout en conservant l\'esprit du menu.\r\n',1,45.00,6,0,1,'assets/menus/regime/vegetarien/vegetarien_menu.png','Image du Végétarien - Menu Jardin gourmand'),(17,'Vegan - Menu végétal','Régime particulier','Le Menu Végétal propose une cuisine 100 % végétale où créativité, gourmandise et raffinement sont à l\'honneur. Chaque plat met en valeur des ingrédients soigneusement sélectionnés, des légumes de saison, des céréales, des légumineuses et des fruits frais afin d\'offrir une expérience culinaire équilibrée, généreuse et pleine de saveurs.\r\n',NULL,NULL,'Commande à effectuer au minimum 7 jours avant la prestation.\r\nMenu élaboré exclusivement à partir d\'ingrédients d\'origine végétale.\r\nLes légumes et fruits sont sélectionnés en priorité selon la saison et auprès de producteurs locaux lorsque cela est possible.\r\nConservation entre 0 °C et 4 °C jusqu\'au moment du service.\r\nLes préparations sont à consommer dans les 24 heures suivant la livraison.\r\nLes plats sont livrés prêts à être servis ou accompagnés d\'une fiche de remise en température\r\n',1,45.00,2,0,1,'assets/menus/regime/vegan/vegan_menu.png','Image du Vegan - Menu végétal'),(18,'Sans gluten - Menu équilibre','Régime particulier','Le Menu Équilibre est une invitation à savourer une cuisine légère, raffinée et naturellement sans gluten. Élaboré à partir d\'ingrédients soigneusement sélectionnés, il met en valeur les produits frais, les légumes de saison et les protéines de qualité dans des recettes gourmandes, parfaitement équilibrées.\r\n',NULL,NULL,'',1,45.00,9,0,1,'assets/menus/regime/sans_gluten/sans_gluten_menu.png','Image du Sans gluten - Menu équilibre');
