/*!40000 ALTER TABLE `entree` DISABLE KEYS */;
INSERT INTO `entree` (`entree_id`, `nom_entree`, `description`, `menu_id`, `theme`, `allergenes`, `image_url`, `image_alt`, `actif`) VALUES (1,'Millefeuille de légumes grillés, chèvre frais et pesto de basilic\r\n','Une entrée colorée associant des légumes de saison délicatement grillés, du chèvre frais onctueux et un pesto de basilic maison.\r\n',1,'Classique','Lait\r\nFruits à coque (pignons de pin)\r\n','assets/menus/classiques/decouverte/decouverte_entree.png','Entrée du Menu Découverte',1),(2,'Aumônière croustillante de chèvre, miel et noix\r\n','Une fine feuille de brick garnie de chèvre fondant, relevée d\'une touche de miel et de noix croquantes, accompagnée d\'une salade de jeunes pousses assaisonnée d\'une vinaigrette maison.\r\n',2,'Classique','Gluten\r\nLait\r\nFruits à coque\r\n','assets/menus/classiques/signature/signature_entree.png','Entrée du Menu Signature',1),(3,'Saint-Jacques snackées, crème de panais et éclats de noisettes\r\n','De délicates noix de Saint-Jacques juste snackées, servies sur une crème de panais onctueuse, accompagnées de noisettes torréfiées et d\'une huile aux herbes.\r\n',3,'Classique','Mollusques\r\nLait\r\nFruits à coque\r\n','assets/menus/classiques/prestige/prestige_entree.png','Entrée du Menu Prestige',1),(4,'Cannelé salé au chèvre frais, jambon de Bayonne et jeunes pousses\r\n','Une revisite originale du célèbre cannelé bordelais, garni de chèvre frais, de jambon de Bayonne et accompagné d\'une salade de jeunes pousses assaisonnée d\'une vinaigrette aux noix.\r\n',4,'Classique','Gluten\r\nLait\r\nŒufs\r\nFruits à coque\r\n','assets/menus/classiques/terroir/terroir_entree.png','Entrée du Menu Terroir',1),(5,'Duo de foie gras mi-cuit et saumon gravlax, brioche toastée et chutney de figues\r\n','Une entrée raffinée associant un foie gras mi-cuit fondant, un saumon gravlax délicatement parfumé aux agrumes, accompagné d\'une brioche légèrement toastée et d\'un chutney de figues maison.\r\n',5,'Événementiel','Poisson\r\nGluten\r\nLait\r\nŒufs\r\n','assets/menus/evenementiels/mariage/mariage_entree.png','Entrée du Menu Mariage',1),(6,'Tartare de saumon aux agrumes, avocat et jeunes pousses\r\n','Un tartare de saumon frais relevé d\'une vinaigrette aux agrumes, accompagné d\'avocat, de jeunes pousses et d\'une touche de ciboulette fraîche.\r\n',6,'Événementiel','Poisson\r\nMoutarde\r\n','assets/menus/evenementiels/seminaire/seminaire_entree.png','Entrée du Menu Séminaire',1),(7,'Ballotine de volaille fermière, cœur au foie gras et chutney d\'oignons rouges\r\n','Une ballotine de volaille délicatement farcie au foie gras, servie avec un chutney d\'oignons rouges légèrement confits et une salade de jeunes pousses.\r\n',7,'Événementiel','Œufs\r\nLait\r\nSulfites\r\n','assets/menus/evenementiels/anniversaire/anniversaire_entree.png','Entrée du Menu Anniversaire',1),(8,'Asperges vertes rôties, œuf parfait et copeaux de parmesan\r\n','De belles asperges vertes de saison rôties au four, accompagnées d\'un œuf parfait, de copeaux de parmesan, de jeunes pousses et d\'une vinaigrette aux herbes fraîches.\r\n',8,'Saisonnier','Œufs\r\nLait\r\n','assets/menus/saisonniers/printemps/saveurs_printemps/saveurs_printemps_entree.png','Entrée du Menu Saveurs de printemps',0),(9,'Œuf parfait, asperges vertes, jambon de Bayonne croustillant et crème légère au parmesan\r\n','Un œuf parfait servi sur un lit d\'asperges vertes de saison, accompagné de jambon de Bayonne croustillant, de copeaux de parmesan et d\'une crème légère parfumée aux herbes fraîches.\r\n',9,'Saisonnier','Œufs\r\nLait\r\n','assets/menus/saisonniers/printemps/paques/paques_entree.png','Entrée du Menu Pâques',0),(10,'Burrata crémeuse, tomates anciennes, pesto de basilic et pignons de pin\r\n','Une burrata fondante accompagnée d\'un assortiment de tomates anciennes, d\'un pesto de basilic maison, de pignons de pin torréfiés et d\'un filet d\'huile d\'olive extra vierge.\r\n',10,'Saisonnier','Lait\r\nFruits à coque (pignons de pin)\r\n','assets/menus/saisonniers/ete/saveurs_ete/saveurs_ete_entree.png','Entrée du Menu Saveurs d\'été',1),(11,'Carpaccio de bœuf, copeaux de parmesan, roquette et tomates confites\r\n','De fines tranches de bœuf assaisonnées d\'une vinaigrette au citron, accompagnées de roquette, de tomates confites, de copeaux de parmesan et de pignons de pin torréfiés.\r\n',11,'Saisonnier','Lait\r\nFruits à coque (pignons de pin)\r\n','assets/menus/saisonniers/ete/garden_party/garden_party_entree.png','Entrée du Menu Garden party',1),(12,'Velouté de potimarron, éclats de châtaignes, crème légère et huile de noisette\r\n','Un velouté onctueux de potimarron accompagné de châtaignes grillées, d\'une crème légère parfumée et d\'un filet d\'huile de noisette.\r\n',12,'Saisonnier','Lait\r\nFruits à coque (noisettes)\r\n','assets/menus/saisonniers/automne/saveurs_automne/saveurs_automne_entree.png','Entrée du Menu Saveurs d\'automne',0),(13,'Salade gourmande de magret fumé, raisins frais, figues rôties et noix\r\n','Une salade composée de jeunes pousses, de fines tranches de magret de canard fumé, de raisins blancs et noirs, de figues légèrement rôties, de noix croquantes et d\'une vinaigrette au miel.\r\n',13,'Saisonnier','Fruits à coque (noix)\r\nMoutarde\r\n','assets/menus/saisonniers/automne/vendange/vendange_entree.png','Entrée du Menu Vendange',0),(14,'Velouté de topinambours, chips de lard fumé et noisettes torréfiées\r\n','Un velouté onctueux de topinambours relevé d\'une pointe de crème, garni de chips de lard fumé croustillantes, de noisettes torréfiées et de ciboulette fraîche.\r\n',14,'Saisonnier','Lait\r\nFruits à coque (noisettes)\r\n','assets/menus/saisonniers/hiver/saveurs_hiver/saveurs_hiver_entree.png','Entrée du Menu Saveurs d\'hiver',0),(15,'Foie gras de canard mi-cuit, chutney de figues, pain d\'épices toasté et jeunes pousses\r\n','Un foie gras de canard mi-cuit accompagné d\'un chutney de figues maison, de fines tranches de pain d\'épices légèrement toastées et d\'un bouquet de jeunes pousses.\r\n',15,'Saisonnier','Gluten\r\nŒufs\r\nLait\r\n','assets/menus/saisonniers/hiver/noel_gourmand/noel_gourmand_entree.png','Entrée du Menu Noël Gourmand',0),(16,'Tatin de légumes anciens, chèvre frais, miel et noix torréfiées\r\n','Une fine pâte feuilletée garnie de carottes, panais et betteraves rôtis, accompagnée d\'un chèvre frais légèrement fondant, d\'un filet de miel et de noix torréfiées.\r\n',16,'Régime particulier','Gluten\r\nLait\r\nFruits à coque (noix)\r\n','assets/menus/regime/vegetarien/vegetarien_entree.png','Entrée du Végétarien - Menu Jardin gourmand',1),(17,'Carpaccio de betteraves multicolores, crème de cajou citronnée, grenade et noisettes torréfiées\r\n','De fines lamelles de betteraves jaunes, rouges et chioggia, accompagnées d\'une crème de noix de cajou parfumée au citron, de graines de grenade, de noisettes torréfiées et de jeunes pousses.\r\n',17,'Régime particulier','Fruits à coque (cajou, noisettes)\r\n','assets/menus/regime/vegan/vegan_entree.png','Entrée du Vegan - Menu végétal',1),(18,'Tartare de saumon, avocat, mangue et citron vert\r\n','Un tartare de saumon frais relevé d\'une vinaigrette au citron vert, accompagné d\'avocat fondant, de mangue fraîche, de graines de sésame et de jeunes pousses.\r\n',18,'Régime particulier','Poisson\r\nSésame\r\n','assets/menus/regime/sans_gluten/sans_gluten_entree.png','Entrée du Sans gluten - Menu équilibre',1);
