INSERT INTO `plat` (`plat_id`, `nom_plat`, `description`, `menu_id`, `theme`, `allergenes`, `image_url`, `image_alt`, `actif`) VALUES (1,'Suprême de volaille sauce forestière\r\n','Suprême de poulet rôti accompagné d\'un gratin dauphinois fondant et de légumes de saison.\r\n',1,'Classique','Lait\r\nCéleri\r\n','assets/menus/classiques/decouverte/decouverte_plat.png','Plat du Menu Découverte',1),(2,'Filet de veau, jus réduit au thym et écrasé de pommes de terre à la truffe\r\n','Filet de veau rôti, servi avec un écrasé de pommes de terre parfumé à la truffe et des légumes glacés de saison.\r\n',2,'Classique','Lait\r\nCéleri\r\n','assets/menus/classiques/signature/signature_plat.png','Plat du Menu Signature',1),(3,'Filet de bœuf, sauce aux morilles, gratin dauphinois et légumes glacés\r\n','Un filet de bœuf tendre accompagné d\'une sauce crémeuse aux morilles, d\'un gratin dauphinois fondant et d\'un assortiment de légumes glacés.\r\n',3,'Classique','Lait\r\nCéleri\r\n','assets/menus/classiques/prestige/prestige_plat.png','Plat du Menu Prestige',1),(4,'Magret de canard rôti, sauce au miel et au vin de Bordeaux, pommes grenailles et légumes de saison\r\n','Le traditionnel magret de canard du Sud-Ouest accompagné d\'une sauce légèrement réduite au miel et au vin rouge de Bordeaux, servi avec des pommes grenailles rôties et des légumes de saison.\r\n',4,'Classique','Sulfites\r\nLait\r\n','assets/menus/classiques/terroir/terroir_plat.png','Plat du Menu Terroir',1),(5,'Filet de veau aux morilles, gratin dauphinois fondant et légumes glacés\r\n','Un tendre filet de veau accompagné d\'une sauce crémeuse aux morilles, d\'un gratin dauphinois traditionnel et de légumes glacés de saison.\r\n',5,'Evénementiel','Lait\r\nCéleri\r\n','assets/menus/evenementiels/mariage/mariage_plat.png','Plat du Menu Mariage',1),(6,'Suprême de volaille fermière, crème de parmesan, écrasé de pommes de terre et légumes croquants\r\n','Un suprême de volaille délicatement rôti, servi avec une crème légère au parmesan, un écrasé de pommes de terre maison et un assortiment de légumes de saison.\r\n',6,'Evénementiel','Lait\r\nCéleri\r\n','assets/menus/evenementiels/seminaire/seminaire_plat.png','Plat du Menu Séminaire',1),(7,'Suprême de pintade, sauce forestière, gratin dauphinois et légumes glacés\r\n','Un suprême de pintade rôti accompagné d\'une sauce forestière aux champignons, d\'un gratin dauphinois fondant et de légumes de saison.\r\n',7,'Evénementiel','Lait\r\nCéleri\r\n','assets/menus/evenementiels/anniversaire/anniversaire_plat.png','Plat du Menu Anniversaire',1),(8,'Filet de volaille fermière, crème légère aux herbes, petits pois, fèves et pommes grenailles\r\n','Un filet de volaille délicatement rôti, accompagné d\'une crème légère aux herbes fraîches, de petits pois, de fèves, de pommes grenailles rôties et de jeunes carottes.\r\n',8,'Saisonnier','Lait\r\nCéleri\r\n','assets/menus/saisonniers/printemps/saveurs_printemps/saveurs_printemps_plat.png','Plat du Menu Saveurs de printemps',0),(9,'Carré d\'agneau rôti aux herbes, gratin dauphinois et légumes printaniers\r\n','Un carré d\'agneau tendre rôti au thym et au romarin, accompagné d\'un gratin dauphinois maison, de carottes fanes, petits pois, fèves et asperges vertes.\r\n',9,'Saisonnier','Lait\r\nCéleri\r\n','assets/menus/saisonniers/printemps/paques/paques_plat.png','Plat du Menu Pâques',0),(10,'Filet de dorade royale, risotto aux courgettes, citron confit et légumes du soleil\r\n','Un filet de dorade royale délicatement rôti, accompagné d\'un risotto crémeux aux courgettes, de citron confit, de tomates cerises rôties et d\'un assortiment de légumes du soleil.\r\n',10,'Saisonnier','Poisson\r\nLait\r\nCéleri\r\n','assets/menus/saisonniers/ete/saveurs_ete/saveurs_ete_plat.png','Plat du Menu Saveurs d\'été',1),(11,'Suprême de poulet fermier grillé, pommes grenailles rôties, légumes méditerranéens et sauce vierge\r\n','Un suprême de poulet grillé servi avec des pommes grenailles croustillantes, des courgettes, aubergines et poivrons grillés, accompagné d\'une sauce vierge aux tomates, basilic et huile d\'olive.\r\n',11,'Saisonnier','Aucun allergène majeur (traces possibles selon les préparations)\r\n','assets/menus/saisonniers/ete/garden_party/garden_party_plat.png','Plat du Menu Garden party',1),(12,'Filet de canard rôti, écrasé de patates douces, poêlée de champignons forestiers et jus réduit au thym\r\n','Un filet de canard rôti à la cuisson rosée, accompagné d\'un écrasé de patates douces maison, d\'un mélange de cèpes, girolles et pleurotes sautés, sublimé par un jus réduit parfumé au thym.\r\n',12,'Saisonnier','Lait\r\nCéleri\r\n','assets/menus/saisonniers/automne/saveurs_automne/saveurs_automne_plat.png','Plat du Menu Saveurs d\'automne',0),(13,'Filet mignon de porc rôti, écrasé de pommes de terre aux herbes, cèpes poêlés et jus réduit au thym\r\n','Un filet mignon tendre accompagné d\'un écrasé de pommes de terre maison, de cèpes poêlés au beurre et d\'un jus parfumé au thym frais.\r\n',13,'Lait\r\nCéleri\r\n','','assets/menus/saisonniers/automne/vendange/vendange_plat.png','Plat du Menu Vendange',0),(14,'Joue de bœuf braisée, purée de céleri-rave, carottes glacées et jus réduit\r\n','Une joue de bœuf mijotée pendant de longues heures jusqu\'à obtenir une viande fondante, accompagnée d\'une purée de céleri-rave, de carottes glacées au beurre et d\'un jus corsé parfumé au thym.\r\n',14,'Saisonnier','Lait\r\nCéleri\r\n','assets/menus/saisonniers/hiver/saveurs_hiver/saveurs_hiver_plat.png','Plat du Menu Saveurs d\'hiver',0),(15,'Suprême de chapon farci aux morilles, écrasé de pommes de terre truffé, marrons glacés et légumes d\'hiver\r\n','Un suprême de chapon farci aux morilles, accompagné d\'un écrasé de pommes de terre parfumé à la truffe, de marrons glacés au beurre et d\'un assortiment de légumes d\'hiver rôtis.\r\n',15,'Saisonnier','Lait\r\nGluten\r\nCéleri\r\n','assets/menus/saisonniers/hiver/noel_gourmand/noel_gourmand_plat.png','Plat du Menu Noël Gourmand',0),(16,'Risotto crémeux aux cèpes, asperges vertes, copeaux de parmesan et huile de truffe\r\n','Un risotto Arborio crémeux préparé avec des cèpes, des asperges vertes, du parmesan affiné et quelques gouttes d\'huile de truffe pour une touche gastronomique.\r\n',16,'Régime particulier','Lait\r\nCéleri\r\n','assets/menus/regime/vegetarien/vegetarien_plat.png','Plat du Végétarien - Menu Jardin gourmand',1),(17,'Steak de chou-fleur rôti, purée de patates douces, pois chiches croustillants et sauce aux champignons\r\n','Une belle tranche de chou-fleur rôtie au four, servie avec une purée onctueuse de patates douces, des pois chiches épicés et croustillants, des champignons poêlés et une sauce végétale crémeuse aux champignons.\r\n',17,'Régime particulier','Céleri','assets/menus/regime/vegan/vegan_plat.png','Plat du Vegan - Menu végétal',1),(18,'Suprême de volaille rôti, écrasé de patates douces, légumes croquants et jus au thym\r\n','Un suprême de volaille rôti accompagné d\'un écrasé de patates douces, d\'un assortiment de légumes de saison légèrement croquants et d\'un jus réduit parfumé au thym.\r\n',18,'Régime particulier','Lait\r\nCéleri','assets/menus/regime/sans_gluten/sans_gluten_plat.png','Plat du Sans gluten - Menu équilibre',1);
