INSERT INTO `dessert` (`dessert_id`, `nom_dessert`, `description`, `menu_id`, `theme`, `allergenes`, `image_url`, `image_alt`, `actif`) VALUES (1,'Tarte fine aux pommes caramélisées\r\n','Tarte croustillante garnie de pommes caramélisées, servie avec une crème légère à la vanille.\r\n',1,'Classique','Gluten\r\nLait\r\nŒufs\r\n','assets/menus/classiques/decouverte/decouverte_dessert.png','Dessert du Menu Découverte',1),(2,'Entremets chocolat noir, praliné croustillant et cœur caramel\r\n','Un dessert gourmand associant une mousse au chocolat noir, un praliné croustillant et un cœur fondant au caramel.\r\n',2,'Classique','Gluten\r\nLait\r\nŒufs\r\nFruits à coque\r\n','assets/menus/classiques/signature/signature_dessert.png','Dessert du Menu Signature',1),(3,'Dôme chocolat Grand Cru, cœur framboise et croustillant praliné\r\n','Un dessert élégant composé d\'une mousse au chocolat Grand Cru, d\'un cœur fondant à la framboise et d\'une base croustillante au praliné.\r\n',3,'Classique','Gluten\r\nLait\r\nŒufs\r\nFruits à coque\r\n','assets/menus/classiques/prestige/prestige_dessert.png','Dessert du Menu Prestige',1),(4,'Cannelé bordelais, crème légère à la vanille et caramel beurre salé\r\n','Le grand classique de la pâtisserie bordelaise, accompagné d\'une crème légère à la vanille et d\'un filet de caramel beurre salé.\r\n',4,'Classique','Gluten\r\nLait\r\nŒufs\r\n','assets/menus/classiques/terroir/terroir_dessert.png','Dessert du Menu Terroir',1),(5,'Entremets mariage chocolat blanc, framboise et vanille Bourbon\r\n','Un entremets élégant composé d\'une mousse légère à la vanille Bourbon, d\'un cœur fondant à la framboise, d\'un biscuit moelleux aux amandes et d\'un glaçage miroir au chocolat blanc.\r\n',5,'Événementiel','Gluten\r\nLait\r\nŒufs\r\nFruits à coque\r\n','assets/menus/evenementiels/mariage/mariage_dessert.png','Dessert du Menu Mariage',1),(6,'Tartelette fine aux fruits de saison et crème légère à la vanille\r\n','Une pâte sablée croustillante garnie d\'une crème légère à la vanille et de fruits frais de saison soigneusement sélectionnés.\r\n',6,'Événementiel','Gluten\r\nLait\r\nŒufs\r\n','assets/menus/evenementiels/seminaire/seminaire_dessert.png','Dessert du Menu Séminaire',1),(7,'Royal chocolat et praliné croquant\r\n','Un entremets composé d\'une mousse au chocolat noir, d\'un biscuit moelleux aux amandes, d\'un croustillant praliné et d\'une fine couche de ganache.\r\n',7,'Événementiel','Gluten\r\nLait\r\nŒufs\r\nFruits à coque\r\n','assets/menus/evenementiels/anniversaire/anniversaire_dessert.png','Dessert du Menu Anniversaire',1),(8,'Pavlova aux fraises, framboises et crème légère à la vanille\r\n','Une meringue croustillante garnie d\'une crème légère à la vanille Bourbon, de fraises et de framboises fraîches, relevée de quelques feuilles de menthe.\r\n',8,'Saisonnier','Œufs\r\nLait\r\n','assets/menus/saisonniers/printemps/saveurs_printemps/saveurs_printemps_dessert.png','Dessert du Menu Saveurs de printemps',0),(9,'Dôme chocolat noir, cœur praliné et éclats de noisettes\r\n','Un élégant dôme au chocolat noir renfermant un cœur fondant au praliné, accompagné d\'une mousse légère au chocolat et de noisettes torréfiées.\r\n',9,'Saisonnier','Gluten\r\nLait\r\nŒufs\r\nFruits à coque (noisettes)\r\n','assets/menus/saisonniers/printemps/paques/paques_dessert.png','Dessert du Menu Pâques',0),(10,'Tarte fine aux abricots rôtis, miel de lavande et glace à la vanille\r\n','Une pâte feuilletée croustillante garnie d\'abricots rôtis au miel de lavande, servie avec une glace artisanale à la vanille et quelques pistaches concassées.\r\n',10,'Saisonnier','Gluten\r\nLait\r\nŒufs\r\nFruits à coque (pistaches)\r\n','assets/menus/saisonniers/ete/saveurs_ete/saveurs_ete_dessert.png','Dessert du Menu Saveurs d\'été',1),(11,'Pavlova aux fruits rouges, pêche et chantilly légère à la vanille\r\n','Une meringue croustillante garnie d\'une chantilly légère à la vanille, de fraises, framboises, myrtilles et quartiers de pêche fraîche.\r\n',11,'Saisonnier','Œufs\r\nLait\r\n','assets/menus/saisonniers/ete/garden_party/garden_party_dessert.png','Dessert du Menu Garden party',1),(12,'Tarte fine aux poires caramélisées, noix et crème légère à la vanille\r\n','Une pâte feuilletée croustillante garnie de poires fondantes caramélisées, de noix croquantes et d\'une crème légère à la vanille.\r\n',12,'Saisonnier','Gluten\r\nLait\r\nŒufs\r\nFruits à coque (noix)\r\n','assets/menus/saisonniers/automne/saveurs_automne/saveurs_automne_dessert.png','Dessert du Menu Saveurs d\'automne',0),(13,'Tarte aux figues fraîches, crème d\'amandes et raisins caramélisés\r\n','Une pâte sablée croustillante garnie d\'une crème d\'amandes, de figues fraîches, de raisins légèrement caramélisés et d\'une touche de miel.\r\n',13,'Saisonnier','Gluten\r\nŒufs\r\nLait\r\nFruits à coque (amandes)\r\n','assets/menus/saisonniers/automne/vendange/vendange_dessert.png','Dessert du Menu Vendange',0),(14,'Tarte fine aux pommes caramélisées, crème à la cannelle et éclats d\'amandes\r\n','Une pâte feuilletée croustillante garnie de pommes fondantes caramélisées, servie avec une crème légère parfumée à la cannelle et quelques amandes effilées torréfiées.\r\n',14,'Saisonnier','Gluten\r\nŒufs\r\nLait\r\nFruits à coque (amandes)\r\n','assets/menus/saisonniers/hiver/saveurs_hiver/saveurs_hiver_dessert.png','Dessert du Menu Saveurs d\'hiver',0),(15,'Bûche de Noël chocolat, praliné et noisettes caramélisées\r\n','Une bûche de Noël composée d\'une mousse au chocolat noir, d\'un cœur fondant au praliné, d\'un biscuit moelleux et d\'un glaçage miroir, décorée de noisettes caramélisées et de feuilles d\'or alimentaire.\r\n',15,'Saisonnier','Gluten\r\nŒufs\r\nLait\r\nFruits à coque (noisettes)\r\n','assets/menus/saisonniers/hiver/noel_gourmand/noel_gourmand_dessert.png','Dessert du Menu Noël Gourmand',0),(16,'Pavlova aux fruits rouges, crème légère à la vanille et éclats de pistaches\r\n','Une meringue croustillante garnie d\'une crème légère à la vanille, de fraises, framboises et myrtilles fraîches, sublimée par quelques pistaches concassées.\r\n',16,'Régime particulier','Œufs\r\nLait\r\nFruits à coque (pistaches)\r\n','assets/menus/regime/vegetarien/vegetarien_dessert.png','Dessert du Végétarien - Menu Jardin gourmand',1),(17,'Tartelette chocolat noir, ganache végétale et fruits rouges frais\r\n','Une pâte sablée végétale garnie d\'une ganache au chocolat noir réalisée avec du lait de coco, accompagnée de fraises, framboises et myrtilles fraîches.\r\n',17,'Régime particulier','Gluten\r\nSoja\r\nFruits à coque (selon le chocolat utilisé)\r\n','assets/menus/regime/vegan/vegan_dessert.png','Dessert du Vegan - Menu végétal',1),(18,'Pavlova aux agrumes, fruits exotiques et coulis de passion\r\n','Une meringue croustillante garnie d\'une crème légère, de segments d\'orange, de pamplemousse, de mangue et de kiwi, accompagnée d\'un coulis de fruits de la passion.\r\n',18,'Régime particulier','Œufs\r\nLait\r\n','assets/menus/regime/sans_gluten/sans_gluten_dessert.png','Dessert du Sans gluten - Menu équilibre',1);
